theme_rdc <- function(base_size = 13) {
  theme_minimal(base_size = base_size) +
    theme(panel.grid.minor = element_blank(),
          panel.grid.major.x = element_blank(),
          panel.grid.major.y = element_line(color = "#E3E3E3", linewidth = 0.4),
          axis.line.x = element_line(color = "#B0B0B0", linewidth = 0.4),
          plot.title = element_text(face = "bold", size = base_size + 2),
          plot.subtitle = element_text(color = "#555555"),
          plot.caption = element_text(color = "#777777", size = base_size - 3, hjust = 0),
          strip.text = element_text(face = "bold", size = base_size - 1),
          legend.position = "top",
          legend.title = element_blank(),
          plot.title.position = "plot",
          plot.caption.position = "plot",
          plot.background = element_rect(fill = "white", color = NA))
}
save_fig <- function(plot, name, height_px = 900) {
  # 1400 px wide at 150 dpi = 9.33 in wide; the text stays readable when shown 1000 px wide
  ggsave(file.path(fig_dir, name), plot, width = 1400 / 150, height = height_px / 150,
         dpi = 150, bg = "white")
  cat("saved figure:", file.path("figures", name), "\n")
}
wrap_txt <- function(x, w) paste(strwrap(x, width = w), collapse = "\n")
# p value in APA style for figure labels
fp <- function(p) ifelse(p < .001, "p < .001", paste0("p = ", sub("^0", "", sprintf("%.3f", p))))
# p value for the output file: five decimals, scientific notation below 0.0001
pf <- function(p) ifelse(p < 0.0001, sprintf("%.2e", p), sprintf("%.5f", p))
# Wilcoxon and Mann Whitney statistics: whole number, or one decimal when ties give a half rank
fv <- function(v) ifelse(abs(v - round(v)) < 1e-9, sprintf("%.0f", v), sprintf("%.1f", v))
ci95 <- function(x) { x <- x[!is.na(x)]; qt(0.975, length(x) - 1) * sd(x) / sqrt(length(x)) }

# Confidence limits for a standardized effect size from the NONCENTRAL t distribution (the exact
# method; Lakens, 2013). The observed t is treated as a draw from a t distribution with an unknown
# noncentrality parameter (ncp); the 95% limits are the two ncp values for which the observed t sits
# at the 97.5th and the 2.5th percentile. Dividing the ncp limits by sqrt(n) (paired) or multiplying
# them by sqrt(1/n1 + 1/n2) (two groups) turns them into d limits.
nct_limits <- function(t_obs, df, conf = 0.95) {
  a <- (1 - conf) / 2
  f <- function(ncp, target) suppressWarnings(pt(t_obs, df, ncp)) - target
  lo <- uniroot(f, c(t_obs - 15, t_obs + 15), target = 1 - a, tol = 1e-12)$root
  hi <- uniroot(f, c(t_obs - 15, t_obs + 15), target = a, tol = 1e-12)$root
  c(lo, hi)
}

# Empty result list with every field the summary table needs (filled by the helpers below)
res_template <- function(id, test, label) {
  list(id = id, test = test, label = label, n = NA_integer_, n1 = NA_integer_, n2 = NA_integer_,
       m1 = NA_real_, m2 = NA_real_, sd1 = NA_real_, sd2 = NA_real_, diff = NA_real_, sd_diff = NA_real_,
       sd_pooled = NA_real_, ci_lo = NA_real_, ci_hi = NA_real_, stat_name = NA_character_, stat = NA_real_,
       df = NA_real_, p = NA_real_, p_holm = NA_real_, es_type = NA_character_, es = NA_real_, es_lo = NA_real_,
       es_hi = NA_real_, es_lo_approx = NA_real_, es_hi_approx = NA_real_, g = NA_real_, g_lo = NA_real_,
       g_hi = NA_real_, g_lo_approx = NA_real_, g_hi_approx = NA_real_, np_test = NA_character_,
       np_stat = NA_real_, np_p = NA_real_, shapiro_p = NA_real_, note = NA_character_)
}

# ---- Helper: paired t test as a one sample t test on the differences ---------------------
# x_ref and x_cmp are the two measurements of the same respondents; difference = x_cmp - x_ref.
# Cohen's d_z = mean difference / SD of the differences, the effect size of a paired design
# (t = d_z x sqrt(n)). Two 95% intervals are printed: the exact one from the noncentral t
# distribution and the large sample approximation SE(d_z) = sqrt(1 / n + d_z^2 / (2 n)) that the
# Excel workbook uses.
report_paired <- function(x_ref, x_cmp, label, nm_ref, nm_cmp, id, unit = "") {
  ok <- !is.na(x_ref) & !is.na(x_cmp)
  a <- x_ref[ok]; b <- x_cmp[ok]; d <- b - a; n <- length(d)
  tt <- t.test(d, mu = 0)
  dz <- mean(d) / sd(d)
  lim <- nct_limits(unname(tt$statistic), n - 1) / sqrt(n)
  se_d <- sqrt(1 / n + dz^2 / (2 * n))
  wx <- suppressWarnings(wilcox.test(b, a, paired = TRUE, exact = FALSE))
  sw <- shapiro.test(d)
  cat(sprintf("%s\n", label))
  cat(sprintf("  %s: M = %.3f, SD = %.3f, median = %.3f, n = %d\n", nm_ref, mean(a), sd(a), median(a), n))
  cat(sprintf("  %s: M = %.3f, SD = %.3f, median = %.3f, n = %d\n", nm_cmp, mean(b), sd(b), median(b), n))
  cat(sprintf("  Difference (%s minus %s): M = %.3f%s, SD = %.3f, 95%% CI [%.3f, %.3f]\n",
              nm_cmp, nm_ref, mean(d), unit, sd(d), tt$conf.int[1], tt$conf.int[2]))
  cat(sprintf("  Paired t (one sample t on the differences): t(%d) = %.2f, p = %s (two tailed)\n", n - 1, tt$statistic, pf(tt$p.value)))
  cat(sprintf("  Cohen's d_z = %.2f, 95%% CI [%.2f, %.2f] (noncentral t); approximation [%.2f, %.2f]\n",
              dz, lim[1], lim[2], dz - 1.96 * se_d, dz + 1.96 * se_d))
  cat(sprintf("  Wilcoxon signed rank V = %s, p = %s (zero differences are dropped: %d)\n", fv(wx$statistic), pf(wx$p.value), sum(d == 0)))
  cat(sprintf("  Shapiro Wilk on the differences: W = %.3f, p = %s\n", sw$statistic, pf(sw$p.value)))
  cat(sprintf("  Respondents with a positive difference: %d of %d; negative: %d; zero: %d\n\n", sum(d > 0), n, sum(d < 0), sum(d == 0)))
  r <- res_template(id, "paired t (one sample t on the differences)", label)
  r[c("n", "m1", "m2", "sd1", "sd2", "diff", "sd_diff", "ci_lo", "ci_hi", "stat_name", "stat", "df", "p", "es_type", "es",
      "es_lo", "es_hi", "es_lo_approx", "es_hi_approx", "np_test", "np_stat", "np_p", "shapiro_p")] <-
    list(n, mean(a), mean(b), sd(a), sd(b), mean(d), sd(d), tt$conf.int[1], tt$conf.int[2], "t", unname(tt$statistic), n - 1,
         tt$p.value, "d_z", dz, lim[1], lim[2], dz - 1.96 * se_d, dz + 1.96 * se_d, "Wilcoxon signed rank V",
         unname(wx$statistic), wx$p.value, sw$p.value)
  r$d <- d; r$a <- a; r$b <- b
  r
}

# ---- Helper: Welch t test between two groups ------------------------------------------
# Welch's t does not assume equal variances (Delacre, Lakens, & Leys, 2017). Cohen's d uses the
# pooled SD; Hedges' g = J x d with the small sample correction J = 1 - 3 / (4 (n1 + n2) - 9).
# Their exact 95% limits come from the noncentral t distribution of the pooled (Student) t; the
# approximation SE(g) = sqrt((n1 + n2) / (n1 n2) + g^2 / (2 (n1 + n2))) is what Excel uses.
report_welch <- function(xa, xb, label, nm_a, nm_b, id) {
  xa <- xa[!is.na(xa)]; xb <- xb[!is.na(xb)]
  n1 <- length(xa); n2 <- length(xb)
  wt <- t.test(xa, xb, var.equal = FALSE)
  stt <- t.test(xa, xb, var.equal = TRUE)
  sp <- sqrt(((n1 - 1) * var(xa) + (n2 - 1) * var(xb)) / (n1 + n2 - 2))
  d <- (mean(xa) - mean(xb)) / sp
  J <- 1 - 3 / (4 * (n1 + n2) - 9)
  g <- J * d
  lim <- nct_limits(unname(stt$statistic), n1 + n2 - 2) * sqrt(1 / n1 + 1 / n2)
  se_d <- sqrt((n1 + n2) / (n1 * n2) + d^2 / (2 * (n1 + n2)))
  se_g <- sqrt((n1 + n2) / (n1 * n2) + g^2 / (2 * (n1 + n2)))
  mw <- suppressWarnings(wilcox.test(xa, xb, exact = FALSE))
  sw_a <- shapiro.test(xa); sw_b <- shapiro.test(xb)
  cat(sprintf("%s\n", label))
  cat(sprintf("  %s: M = %.3f, SD = %.3f, median = %.1f, n = %d\n", nm_a, mean(xa), sd(xa), median(xa), n1))
  cat(sprintf("  %s: M = %.3f, SD = %.3f, median = %.1f, n = %d\n", nm_b, mean(xb), sd(xb), median(xb), n2))
  cat(sprintf("  Difference (%s minus %s) = %.3f, 95%% CI [%.3f, %.3f] (Welch)\n", nm_a, nm_b, mean(xa) - mean(xb),
              wt$conf.int[1], wt$conf.int[2]))
  cat(sprintf("  Welch t(%.2f) = %.2f, p = %s (two tailed)\n", wt$parameter, wt$statistic, pf(wt$p.value)))
  cat(sprintf("  Student t(%d) = %.2f, p = %s (equal variances assumed; used only for the effect size interval)\n",
              n1 + n2 - 2, stt$statistic, pf(stt$p.value)))
  cat(sprintf("  Pooled SD = %.3f; Cohen's d = %.2f, 95%% CI [%.2f, %.2f]; Hedges' g = %.2f, 95%% CI [%.2f, %.2f] (noncentral t)\n",
              sp, d, lim[1], lim[2], g, J * lim[1], J * lim[2]))
  cat(sprintf("  Approximate intervals: d [%.2f, %.2f], g [%.2f, %.2f]\n", d - 1.96 * se_d, d + 1.96 * se_d, g - 1.96 * se_g, g + 1.96 * se_g))
  cat(sprintf("  Mann Whitney W = %s, p = %s\n", fv(mw$statistic), pf(mw$p.value)))
  cat(sprintf("  Shapiro Wilk: %s p = %s, %s p = %s; variance ratio (larger / smaller) = %.2f\n\n",
              nm_a, pf(sw_a$p.value), nm_b, pf(sw_b$p.value), max(var(xa), var(xb)) / min(var(xa), var(xb))))
  r <- res_template(id, "Welch t (two groups)", label)
  r[c("n", "n1", "n2", "m1", "m2", "sd1", "sd2", "diff", "sd_pooled", "ci_lo", "ci_hi", "stat_name", "stat", "df", "p",
      "es_type", "es", "es_lo", "es_hi", "es_lo_approx", "es_hi_approx", "g", "g_lo", "g_hi", "g_lo_approx", "g_hi_approx",
      "np_test", "np_stat", "np_p", "shapiro_p")] <-
    list(n1 + n2, n1, n2, mean(xa), mean(xb), sd(xa), sd(xb), mean(xa) - mean(xb), sp, wt$conf.int[1], wt$conf.int[2],
         "Welch t", unname(wt$statistic), unname(wt$parameter), wt$p.value, "d (pooled SD)", d, lim[1], lim[2],
         d - 1.96 * se_d, d + 1.96 * se_d, g, J * lim[1], J * lim[2], g - 1.96 * se_g, g + 1.96 * se_g,
         "Mann Whitney W", unname(mw$statistic), mw$p.value, min(sw_a$p.value, sw_b$p.value))
  r$xa <- xa; r$xb <- xb; r$shapiro_a <- sw_a$p.value; r$shapiro_b <- sw_b$p.value
  r
}

# ---- Helper: chi square test of a 2 x 2 table ---------------------------------------------
# Pearson chi square WITHOUT the continuity correction (correct = FALSE), which is what Excel's
# CHISQ.TEST gives; the Yates corrected version that R uses by default is printed next to it.
# phi = sqrt(chi square / N) is the effect size of a 2 x 2 table.
report_chisq <- function(tab, label, id) {
  ct <- suppressWarnings(chisq.test(tab, correct = FALSE))
  cy <- suppressWarnings(chisq.test(tab, correct = TRUE))
  fe <- fisher.test(tab)
  N <- sum(tab)
  phi <- sqrt(unname(ct$statistic) / N)
  cat(sprintf("%s\n", label))
  print(addmargins(tab))
  cat("  Expected counts if the row and the outcome were unrelated:\n")
  print(round(ct$expected, 2))
  cat(sprintf("  Pearson chi square (no continuity correction) X2(%d, N = %d) = %.3f, p = %s; phi = %.3f\n",
              as.integer(ct$parameter), N, ct$statistic, pf(ct$p.value), phi))
  cat(sprintf("  With the Yates continuity correction (R default): X2 = %.3f, p = %s\n", cy$statistic, pf(cy$p.value)))
  cat(sprintf("  Fisher exact test: p = %s; odds ratio = %.2f, 95%% CI [%.2f, %.2f]\n", pf(fe$p.value), fe$estimate,
              fe$conf.int[1], fe$conf.int[2]))
  cat(sprintf("  Smallest expected count = %.2f%s\n\n", min(ct$expected),
              if (min(ct$expected) < 5) " (below 5: report the Fisher exact test)" else " (5 or more: the chi square approximation is fine)"))
  r <- res_template(id, "chi square test of independence (2 x 2)", label)
  r[c("n", "stat_name", "stat", "df", "p", "es_type", "es", "np_test", "np_stat", "np_p")] <-
    list(N, "Pearson X2 (no continuity correction)", unname(ct$statistic), unname(ct$parameter), ct$p.value, "phi", phi,
         "Fisher exact (odds ratio)", unname(fe$estimate), fe$p.value)
  r$note <- sprintf("Yates X2 = %.3f, p = %.4f; smallest expected count %.2f", cy$statistic, cy$p.value, min(ct$expected))
  r$expected_min <- min(ct$expected)
  r
}

# ---- STEP 1. Read the files -----------------------------------------------------------
# The first line of every file is a "# SIMULATED" comment, so comment = "#" skips it. A real export
# has no such line. NA (or an empty cell) marks a value that does not exist, for example the
# fixation metrics of an AOI that a respondent never fixated.
session  <- read_csv("SIMULATED_session_data.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
quality  <- read_csv("SIMULATED_quality.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
fea_raw  <- read_csv("SIMULATED_fea_metrics.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
aoi_raw  <- read_csv("SIMULATED_aoi_metrics.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
survey   <- read_csv("SIMULATED_survey.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
seed_txt <- sub(".*\\(seed ([0-9]+)\\).*", "\\1", readLines("SIMULATED_session_data.csv", n = 1))

cat("---- STEP 1. Files read ----\n")
cat("Seed of the simulation:", seed_txt, "\n")
cat("Session data rows:", nrow(session), " columns:", paste(names(session), collapse = " | "), "\n")
cat("Quality table rows:", nrow(quality), " columns:", paste(names(quality), collapse = " | "), "\n")
cat("FEA export rows:", nrow(fea_raw), " columns:", paste(names(fea_raw), collapse = " | "), "\n")
cat("AOI export rows:", nrow(aoi_raw), " columns:", paste(names(aoi_raw), collapse = " | "), "\n")
cat("Survey rows:", nrow(survey), " columns:", paste(names(survey), collapse = " | "), "\n")
stopifnot(identical(names(session)[1:7], c("Id", "Started", "Ended", "Eye tracking", "Est. face %", "Block", "Status")))
stopifnot(identical(names(fea_raw), c("Study Name", "Respondent Name", "Interval type", "Interval label", "Interval duration (s)",
                                      "Expression", "Threshold", "Percent of time present", "Number of segments",
                                      "Mean raw score (0-100)", "Data quality (%)")))
cat("Expressions:", paste(unique(fea_raw$Expression), collapse = ", "), "; thresholds:",
    paste(unique(paste(fea_raw$Expression, fea_raw$Threshold)), collapse = ", "), "\n")
cat("AOIs:", paste(unique(aoi_raw$`AOI Name`), collapse = ", "), "\n\n")

# ---- STEP 2. Session data -------------------------------------------------------------
# One row per session, that is, per person who opened a study link. Status: Processed = the data
# arrived and were processed; Abandoned = the session stopped before the end (window closed,
# connection lost, or upload interrupted); Errors = the uploaded files were invalid. The documented
# "Eye tracking" column holds TWO numbers in one text cell ("1.9, 96%": accuracy in degrees, then
# eye tracking quality), so it is split here. It is rounded and summarizes the whole session, which
# is why the exclusion rule uses the quality table (step 4) instead.
cat("---- STEP 2. Session data ----\n")
ses <- session %>%
  transmute(id = Id, started = Started, ended = Ended, et_text = `Eye tracking`, face_est = `Est. face %`,
            flow = Block, status = Status, last_step = `Last funnel step (modeled)`,
            device = `Device type (modeled)`, browser = `Browser (modeled)`) %>%
  mutate(order = if_else(flow == "Study flow 1", "Narrative first", "Visual first"),
         step_num = suppressWarnings(as.integer(sub("^STEP ([0-9]+) .*$", "\\1", last_step))),  # NA for "Completed"
         step_num = if_else(last_step == "Completed", 11L, step_num),
         completed = status == "Processed",
         et_acc_session = suppressWarnings(as.numeric(sub(",.*$", "", et_text))),
         et_q_session = suppressWarnings(as.numeric(sub("%", "", sub("^.*, ", "", et_text)))),
         minutes = as.numeric(difftime(ended, started, units = "mins")))
n_open <- nrow(ses)
cat(sprintf("Sessions (opened a link): %d, from %s to %s\n", n_open, format(min(ses$started), "%Y-%m-%d"), format(max(ses$started), "%Y-%m-%d")))
cat("Status:\n"); print(table(ses$status))
cat("Block (study flow) and order:\n"); print(table(ses$flow, ses$order))
cat("\nDevice type (modeled column) by completion:\n")
dev_tab <- ses %>% group_by(device) %>% summarize(opened = n(), completed = sum(completed), .groups = "drop") %>%
  mutate(pct_completed = round(100 * completed / opened, 1)) %>% arrange(desc(opened))
print(as.data.frame(dev_tab), row.names = FALSE)
cat("Browser (modeled column) by completion, computers only:\n")
brw_tab <- ses %>% filter(device %in% c("Laptop", "Desktop")) %>% group_by(browser) %>%
  summarize(opened = n(), completed = sum(completed), .groups = "drop") %>% mutate(pct_completed = round(100 * completed / opened, 1)) %>%
  arrange(desc(opened))
print(as.data.frame(brw_tab), row.names = FALSE)
mob <- ses %>% filter(device %in% c("Phone", "Tablet"))
cat(sprintf("Phones and tablets: %d sessions, %d completed; last step reached: %s\n", nrow(mob), sum(mob$completed),
            paste(names(table(mob$step_num)), "=", table(mob$step_num), collapse = ", ")))
cat(sprintf("Sessions that stopped at STEP 5 Screen size: %d (%d phones or tablets, %d computers)\n", sum(ses$step_num == 5),
            sum(mob$step_num == 5), sum(ses$step_num == 5) - sum(mob$step_num == 5)))
cat("(RDC 'requires a desktop or laptop computer'; 'Participation can not be done on phones or tablets'.)\n")
done <- ses %>% filter(completed)
cat(sprintf("Completed sessions: %d; minutes from opening the link to the end of the upload: median = %.1f, range %.1f to %.1f\n",
            nrow(done), median(done$minutes), min(done$minutes), max(done$minutes)))
cat(sprintf("Session level 'Eye tracking' (completed): accuracy median = %.1f degrees, quality median = %.0f percent; Est. face %%: median = %.0f\n\n",
            median(done$et_acc_session), median(done$et_q_session), median(done$face_est)))

# ---- STEP 3. The respondent funnel ----------------------------------------------------------
# The portal draws the funnel as a chart. Here it is rebuilt from the session level column "Last funnel
# step (modeled)": a session ENTERED a step when its last step is that step or a later one, and it
# STOPPED at the step where it ended. "Sessions that are in progress are not included" (portal note).
cat("---- STEP 3. Respondent funnel ----\n")
funnel <- tibble(step = 1:10, name = STEPS) %>%
  mutate(entered = sapply(step, function(k) sum(ses$step_num >= k)),
         stopped = sapply(step, function(k) sum(ses$step_num == k)),
         continued = entered - stopped,
         pct_of_opened = 100 * entered / n_open,
         pct_of_previous = 100 * entered / lag(entered, default = n_open))
print(as.data.frame(funnel %>% mutate(across(starts_with("pct"), ~ round(.x, 1)))), row.names = FALSE)
n_complete <- sum(ses$completed)
n_err <- sum(ses$status == "Errors")
cat(sprintf("Completed (Status Processed): %d of %d (%.1f percent). Stopped at STEP 10: %d (Abandoned %d, Errors %d).\n",
            n_complete, n_open, 100 * n_complete / n_open, funnel$stopped[10], funnel$stopped[10] - n_err, n_err))
cat(sprintf("Largest single loss: %s (%d sessions); lost before the videos started (STEP 1 to STEP 8): %d (%.1f percent of those who opened the link).\n",
            funnel$name[which.max(funnel$stopped)], max(funnel$stopped), sum(funnel$stopped[1:8]), 100 * sum(funnel$stopped[1:8]) / n_open))
cat("Screen recording was off in this study, so nobody could stop at STEP 3 (modeled).\n")
funnel_flow <- ses %>% group_by(order) %>% summarize(
  opened = n(), reached_step5 = sum(step_num >= 5), reached_step9 = sum(step_num >= 9),
  completed = sum(completed), .groups = "drop") %>% mutate(pct_completed = round(100 * completed / opened, 1))
cat("By order (study flow):\n"); print(as.data.frame(funnel_flow), row.names = FALSE)
cat("\n")

# ---- STEP 4. The exclusion rule ---------------------------------------------------------------
# The quality table has one row per completed respondent and slide. The rule needs five numbers per
# respondent: accuracy at the two calibrations, eye tracking quality on the infographic (the only
# stimulus whose gaze is analyzed), and face quality during each video (the stimuli whose faces are
# analyzed). The same rule applies to every analysis so that H1 to H3 use one sample.
cat("---- STEP 4. Exclusion rule ----\n")
cat(sprintf("Rule (written before collection): exclude when Pre-study OR Post-study accuracy > %.1f degrees, eye tracking quality on\n", ACC_MAX))
cat(sprintf("the infographic < %.0f percent, or face quality < %.0f percent during either video. Sensitivity: both accuracies <= %.1f.\n",
            ETQ_MIN, FACE_MIN, ACC_STRICT))
q <- quality %>% transmute(id = `Respondent Name`, flow = Block, pos = `Slide position`, slide = Slide,
                           acc = `Eye tracking accuracy (degrees)`, etq = `Eye tracking quality (%)`, faceq = `Face quality (%)`)
cat("Slides in the quality table:", paste(unique(q$slide), collapse = ", "), "\n")
reasons <- c(pre = sprintf("Pre-study calibration accuracy above %.1f degrees", ACC_MAX),
             post = sprintf("Post-study calibration accuracy above %.1f degrees", ACC_MAX),
             etq = sprintf("Eye tracking quality on the infographic below %.0f percent", ETQ_MIN),
             face = sprintf("Face quality below %.0f percent during a video", FACE_MIN))
qw <- q %>% group_by(id, flow) %>%
  summarize(pre = acc[slide == "Pre-study calibration"], post = acc[slide == "Post-study calibration"],
            etq_info = etq[slide == "infographic"], face_narr = faceq[slide == NARR], face_vis = faceq[slide == VIS],
            pos_narr = pos[slide == NARR], pos_vis = pos[slide == VIS], .groups = "drop") %>%
  mutate(order = if_else(flow == "Study flow 1", "Narrative first", "Visual first"),
         f_pre = pre > ACC_MAX, f_post = post > ACC_MAX, f_etq = etq_info < ETQ_MIN, f_face = face_narr < FACE_MIN | face_vis < FACE_MIN,
         n_fail = f_pre + f_post + f_etq + f_face,
         keep = n_fail == 0,
         first_reason = case_when(f_pre ~ reasons[["pre"]], f_post ~ reasons[["post"]], f_etq ~ reasons[["etq"]],
                                  f_face ~ reasons[["face"]], TRUE ~ "Kept"),
         max_acc = pmax(pre, post), mean_acc = (pre + post) / 2,
         keep_strict = keep & max_acc <= ACC_STRICT) %>%
  arrange(id)
n_kept <- sum(qw$keep); n_excl <- sum(!qw$keep)
cat(sprintf("\nCompleted respondents screened: %d; excluded: %d (%.1f percent); kept: %d\n", nrow(qw), n_excl, 100 * n_excl / nrow(qw), n_kept))
any_tab <- tibble(reason = unname(reasons), failed_any = c(sum(qw$f_pre), sum(qw$f_post), sum(qw$f_etq), sum(qw$f_face)),
                  first_reason = sapply(unname(reasons), function(r) sum(qw$first_reason == r)))
cat("Exclusions by reason (failed_any counts every respondent who failed the criterion; first_reason assigns each\n")
cat("excluded respondent to the first criterion failed, in the order of the rule, so the column adds up to the total):\n")
print(as.data.frame(any_tab), row.names = FALSE)
cat(sprintf("Respondents who failed more than one criterion: %d\n", sum(qw$n_fail > 1)))
post_only <- qw %>% filter(!f_pre & f_post)
cat(sprintf("Failed ONLY at the Post-study calibration (Pre-study fine, Post-study above %.1f): %d. Their accuracy went from M = %.2f to M = %.2f degrees.\n",
            ACC_MAX, nrow(post_only), mean(post_only$pre), mean(post_only$post)))
cat("These respondents calibrated well and then drifted: a single calibration at the start would have kept them.\n")
kept_flow <- qw %>% group_by(order) %>% summarize(completed = n(), kept = sum(keep), kept_strict = sum(keep_strict), .groups = "drop")
cat("Kept by order:\n"); print(as.data.frame(kept_flow), row.names = FALSE)
n_strict <- sum(qw$keep_strict)
cat(sprintf("Kept under the %.1f degree sensitivity rule: %d (a further %d removed)\n", ACC_STRICT, n_strict, n_kept - n_strict))
ses_chk <- qw %>% left_join(ses %>% select(id, et_acc_session), by = "id")
hidden <- ses_chk %>% filter(et_acc_session <= ACC_MAX & max_acc > ACC_MAX)
cat(sprintf("Respondents whose session level accuracy (the rounded mean of the two calibrations) is %.1f or less although one\n", ACC_MAX))
cat(sprintf("calibration is above %.1f: %d. Screening on the session list alone would have kept them.\n\n", ACC_MAX, nrow(hidden)))

# ---- STEP 5. Differential attrition by order ------------------------------------------------
# Randomization makes the two orders comparable only if the people who stay are comparable. If one
# order made more people quit (for example, the visual video upset some viewers), the completers of
# that order would be a different kind of person (Zhou & Fishbach, 2016). The flow was assigned before
# the link was opened, so the Block column gives the order of EVERY session, including the sessions
# that stopped before the videos.
cat("---- STEP 5. Differential attrition and exclusion by order ----\n")
tab_all <- table(Order = ses$order, Completed = if_else(ses$completed, "Completed", "Not completed"))[, c("Completed", "Not completed")]
res_att <- report_chisq(tab_all, sprintf("(a) Completion by order, all %d sessions that opened a link", n_open), "ATTRITION_ALL")
stim <- ses %>% filter(step_num >= 9)
tab_stim <- table(Order = stim$order, Completed = if_else(stim$completed, "Completed", "Not completed"))[, c("Completed", "Not completed")]
res_att9 <- report_chisq(tab_stim, sprintf("(b) Completion by order among the %d sessions that reached STEP 9 (the videos started)", nrow(stim)), "ATTRITION_STIMULI")
cat("Only the losses from STEP 9 on can depend on the order: before STEP 9 nobody had seen a video. Test (b) is the sharper\n")
cat("check; its expected counts are small, so read its Fisher exact p.\n\n")
tab_ex <- table(Order = qw$order, Kept = if_else(qw$keep, "Kept", "Excluded"))[, c("Kept", "Excluded")]
res_exfl <- report_chisq(tab_ex, sprintf("(c) Exclusion by order among the %d completed respondents", nrow(qw)), "EXCLUSION_ORDER")

# ---- STEP 6. Check the files against each other ---------------------------------------------
cat("---- STEP 6. Consistency checks across the files ----\n")
ids_done <- sort(ses$id[ses$completed])
chk <- c(
  "Processed sessions = respondents in the quality table" = identical(ids_done, sort(unique(q$id))),
  "Processed sessions = respondents in the FEA export" = identical(ids_done, sort(unique(fea_raw$`Respondent Name`))),
  "Processed sessions = respondents in the AOI export" = identical(ids_done, sort(unique(aoi_raw$`Respondent Name`))),
  "Processed sessions = respondents in the survey" = identical(ids_done, sort(unique(survey$`Respondent Name`))),
  "7 slides per respondent in the quality table" = all(table(q$id) == 7),
  "10 FEA rows (2 videos x 5 expressions) per respondent" = all(table(fea_raw$`Respondent Name`) == 10),
  "5 AOI rows per respondent" = all(table(aoi_raw$`Respondent Name`) == 5),
  "Block in the quality table = Block in the session data" =
    all(qw$flow == ses$flow[match(qw$id, ses$id)]),
  "Slide order matches the Block (flow 1: narrative before visual)" =
    all((qw$pos_narr < qw$pos_vis) == (qw$flow == "Study flow 1")),
  "FEA Data quality (%) = face quality of the same video" = {
    fq <- fea_raw %>% distinct(`Respondent Name`, `Interval label`, `Data quality (%)`) %>%
      left_join(q, by = c("Respondent Name" = "id", "Interval label" = "slide"))
    isTRUE(all.equal(fq$`Data quality (%)`, fq$faceq))
  },
  "AOI Valid data = eye tracking quality on the infographic" = {
    av <- aoi_raw %>% distinct(`Respondent Name`, `Valid data`) %>% left_join(qw %>% select(id, etq_info), by = c("Respondent Name" = "id"))
    nrow(av) == length(ids_done) && isTRUE(all.equal(av$`Valid data`, av$etq_info))
  },
  "Session accuracy = mean of the two calibrations, rounded to 0.1" = {
    sa <- ses_chk %>% mutate(m = (pre + post) / 2)
    all(abs(sa$et_acc_session - round(sa$m + 1e-9, 1)) < 0.051)
  },
  "Percent of time present between 0 and Data quality (%)" =
    all(fea_raw$`Percent of time present` >= 0 & fea_raw$`Percent of time present` <= fea_raw$`Data quality (%)` + 0.01),
  "Dwell time (ms) = Fixation count x Fixation duration (ms), within rounding" = {
    a <- aoi_raw %>% filter(!is.na(`Dwell time (ms)`))
    all(abs(a$`Dwell time (ms)` - a$`Fixation count` * a$`Fixation duration (ms)`) <= 0.5 * a$`Fixation count` + 1)
  },
  "TTFF parent (ms) = TTFF AOI (ms) (every AOI is active from the start)" =
    isTRUE(all.equal(aoi_raw$`TTFF parent (ms)`, aoi_raw$`TTFF AOI (ms)`)),
  "No completed session without an Ended time" = all(!is.na(ses$ended[ses$completed])))
for (k in names(chk)) cat(sprintf("  %-72s %s\n", k, if (chk[[k]]) "OK" else "PROBLEM"))
stopifnot(all(chk))
cat("\n")

# ---- STEP 7. Calibration drift ---------------------------------------------------------------
# The same 13 point calibration ran at the start and at the end. Accuracy is an error (degrees), so a
# LARGER number at the end means the gaze estimate got worse while the study ran: people move, lean
# back, or the light changes. This is why the manuals recommend a calibration at the start and at the end.
cat("---- STEP 7. Calibration drift: Pre-study versus Post-study accuracy ----\n")
res_drift <- report_paired(qw$pre, qw$post, sprintf("Accuracy (degrees), all %d completed respondents", nrow(qw)),
                           "Pre-study calibration", "Post-study calibration", "DRIFT_ALL", " degrees")
cat(sprintf("Correlation of the two calibrations: r = %.2f; Post-study worse than Pre-study for %d of %d (%.1f percent)\n",
            cor(qw$pre, qw$post), sum(qw$post > qw$pre), nrow(qw), 100 * mean(qw$post > qw$pre)))
cat(sprintf("Pre-study above %.1f: %d; Post-study above %.1f: %d\n", ACC_MAX, sum(qw$f_pre), ACC_MAX, sum(qw$f_post)))
kq <- qw %>% filter(keep)
res_drift_k <- report_paired(kq$pre, kq$post, sprintf("Accuracy (degrees), kept respondents (n = %d; both values are 4.0 or less by the rule)", nrow(kq)),
                             "Pre-study calibration", "Post-study calibration", "DRIFT_KEPT", " degrees")

# ---- STEP 8. Analysis table: one row per kept respondent ---------------------------------------
cat("---- STEP 8. Analysis table ----\n")
fea <- fea_raw %>% transmute(id = `Respondent Name`, video = `Interval label`, expr = Expression, pct = `Percent of time present`,
                             nseg = `Number of segments`, dq = `Data quality (%)`)
fw <- fea %>% mutate(key = paste0(gsub(" ", "_", expr), if_else(video == NARR, "_narr", "_vis"))) %>%
  select(id, key, pct) %>% pivot_wider(names_from = key, values_from = pct)
aoi <- aoi_raw %>% transmute(id = `Respondent Name`, aoi = `AOI Name`, dwell = `Dwell time (ms)`, ttff = `TTFF AOI (ms)`,
                             fixn = `Fixation count`, dwell_pct = `Dwell time (%)`, size_px = `Size (px2)`, size_pct = `Size (%)`) %>%
  mutate(hit = !is.na(ttff), dwell0 = coalesce(dwell, 0))
aw <- aoi %>% select(id, aoi, dwell0) %>% pivot_wider(names_from = aoi, values_from = dwell0, names_prefix = "dwell_")
hw <- aoi %>% select(id, aoi, hit) %>% pivot_wider(names_from = aoi, values_from = hit, names_prefix = "hit_")
sv <- survey %>% transmute(id = `Respondent Name`, age = Age, gender = Gender, intention = Intention_reduce_food_waste_1to7,
                           pref = More_persuasive_video, recall = Tips_recalled_0to4)
w_all <- qw %>% left_join(ses %>% select(id, device, browser, minutes), by = "id") %>%
  left_join(fw, by = "id") %>% left_join(aw, by = "id") %>% left_join(hw, by = "id") %>% left_join(sv, by = "id") %>%
  mutate(eng_diff = Engagement_vis - Engagement_narr, pref_visual = as.integer(pref == "Visual"),
         tips_dwell = dwell_Tip_1 + dwell_Tip_2 + dwell_Tip_3 + dwell_Tip_4)
w <- w_all %>% filter(keep)
stopifnot(nrow(w) == n_kept, !anyNA(w$Engagement_narr), !anyNA(w$Engagement_vis), !anyNA(w$intention))
cat(sprintf("Kept respondents: %d (Narrative first %d, Visual first %d)\n", nrow(w), sum(w$order == "Narrative first"), sum(w$order == "Visual first")))
cat(sprintf("Kept respondents: %d female, %d male, %d prefer not to say; age M = %.1f, SD = %.1f, range %d to %d; %d aged 18 to 24\n",
            sum(w$gender == "F"), sum(w$gender == "M"), sum(w$gender == "Prefer not to say"), mean(w$age), sd(w$age), min(w$age), max(w$age),
            sum(w$age <= 24)))
cat(sprintf("Kept respondents by device: %s; by browser: %s\n",
            paste(names(table(w$device)), table(w$device), sep = " ", collapse = ", "),
            paste(names(table(w$browser)), table(w$browser), sep = " ", collapse = ", ")))
cat("First six rows:\n")
print(as.data.frame(w %>% select(id, order, pre, post, etq_info, face_narr, face_vis, Engagement_narr, Engagement_vis,
                                 dwell_Tip_1, dwell_Tip_4, intention, pref, recall) %>% head(6)), row.names = FALSE)
cat("\n")

# ---- STEP 9. Descriptive statistics ---------------------------------------------------------
cat("---- STEP 9. Descriptive statistics ----\n")
desc_row <- function(x, measure, group, subgroup = "All") {
  x <- x[!is.na(x)]
  tibble(measure = measure, group = group, subgroup = subgroup, n = length(x), mean = mean(x), sd = sd(x), median = median(x),
         min = min(x), max = max(x), ci_low = mean(x) - ci95(x), ci_high = mean(x) + ci95(x), pct_zero = 100 * mean(x == 0))
}
count_row <- function(measure, group, n, pct = NA_real_, subgroup = "All")
  tibble(measure = measure, group = group, subgroup = subgroup, n = n, mean = pct, sd = NA_real_, median = NA_real_, min = NA_real_,
         max = NA_real_, ci_low = NA_real_, ci_high = NA_real_, pct_zero = NA_real_)
exprs <- c("Engagement", "Joy", "Brow_Furrow", "Positive_Valence", "Negative_Valence")
desc_fea <- bind_rows(lapply(exprs, function(x) bind_rows(
  desc_row(w[[paste0(x, "_narr")]], paste("Percent of time present:", gsub("_", " ", x)), NARR),
  desc_row(w[[paste0(x, "_vis")]], paste("Percent of time present:", gsub("_", " ", x)), VIS))))
cat("Facial expressions, percent of time present (kept respondents; pct_zero = percent of respondents at exactly 0):\n")
print(as.data.frame(desc_fea %>% select(measure, group, n, mean, sd, median, max, pct_zero) %>% mutate(across(where(is.double), ~ round(.x, 2)))), row.names = FALSE)
eng_pos <- w %>% transmute(order, narr_pos = if_else(order == "Narrative first", "first", "second"), Engagement_narr, Engagement_vis) %>%
  group_by(order) %>% summarize(n = n(), narrative = mean(Engagement_narr), visual = mean(Engagement_vis), .groups = "drop")
cat("Engagement by order (descriptive; each video is seen first in one order and second in the other):\n")
print(as.data.frame(eng_pos %>% mutate(across(where(is.double), ~ round(.x, 2)))), row.names = FALSE)
desc_q <- bind_rows(
  desc_row(qw$pre, "Calibration accuracy (degrees)", "Pre-study calibration", "Completed"),
  desc_row(qw$post, "Calibration accuracy (degrees)", "Post-study calibration", "Completed"),
  desc_row(qw$post - qw$pre, "Calibration accuracy (degrees)", "Post minus Pre (drift)", "Completed"),
  desc_row(kq$pre, "Calibration accuracy (degrees)", "Pre-study calibration", "Kept"),
  desc_row(kq$post, "Calibration accuracy (degrees)", "Post-study calibration", "Kept"),
  desc_row(qw$etq_info, "Eye tracking quality (%)", "infographic", "Completed"),
  desc_row(qw$face_narr, "Face quality (%)", NARR, "Completed"),
  desc_row(qw$face_vis, "Face quality (%)", VIS, "Completed"),
  desc_row(w$etq_info, "Eye tracking quality (%)", "infographic", "Kept"),
  desc_row(w$face_narr, "Face quality (%)", NARR, "Kept"),
  desc_row(w$face_vis, "Face quality (%)", VIS, "Kept"))
cat("Data quality:\n")
print(as.data.frame(desc_q %>% select(measure, group, subgroup, n, mean, sd, median, min, max) %>% mutate(across(where(is.double), ~ round(.x, 2)))), row.names = FALSE)
desc_sv <- bind_rows(
  desc_row(w$intention, "Intention to reduce food waste (1 to 7)", "All kept"),
  desc_row(w$intention[w$order == "Narrative first"], "Intention to reduce food waste (1 to 7)", "Narrative first"),
  desc_row(w$intention[w$order == "Visual first"], "Intention to reduce food waste (1 to 7)", "Visual first"),
  desc_row(w$recall, "Tips recalled (0 to 4)", "All kept"),
  desc_row(100 * w$pref_visual, "Visual video named more persuasive (percent)", "All kept"))
cat("Survey (kept respondents):\n")
print(as.data.frame(desc_sv %>% select(measure, group, n, mean, sd, median, min, max) %>% mutate(across(where(is.double), ~ round(.x, 2)))), row.names = FALSE)
cat(sprintf("Visual video named more persuasive: %d of %d (%.1f percent); tips recalled: %s\n", sum(w$pref_visual), nrow(w),
            100 * mean(w$pref_visual), paste(names(table(w$recall)), "=", table(w$recall), collapse = ", ")))
desc_funnel <- bind_rows(
  bind_rows(lapply(1:10, function(k) count_row("Funnel: sessions entering the step", STEPS[k], funnel$entered[k], funnel$pct_of_opened[k]))),
  bind_rows(lapply(1:10, function(k) count_row("Funnel: sessions that stopped at the step", STEPS[k], funnel$stopped[k], 100 * funnel$stopped[k] / n_open))),
  count_row("Funnel: completed (Status Processed)", "Completed", n_complete, 100 * n_complete / n_open),
  count_row("Funnel: kept after the exclusion rule", "Kept (4.0 degrees)", n_kept, 100 * n_kept / n_open),
  count_row("Funnel: kept after the exclusion rule", "Kept (3.0 degrees, sensitivity)", n_strict, 100 * n_strict / n_open),
  bind_rows(lapply(seq_len(nrow(any_tab)), function(k) count_row("Exclusions: first reason", any_tab$reason[k], any_tab$first_reason[k],
                                                                 100 * any_tab$first_reason[k] / nrow(qw)))),
  bind_rows(lapply(seq_len(nrow(any_tab)), function(k) count_row("Exclusions: failed the criterion (any)", any_tab$reason[k], any_tab$failed_any[k],
                                                                 100 * any_tab$failed_any[k] / nrow(qw)))),
  bind_rows(lapply(seq_len(nrow(funnel_flow)), function(k) count_row("Opened the link, by order", funnel_flow$order[k], funnel_flow$opened[k]))),
  bind_rows(lapply(seq_len(nrow(funnel_flow)), function(k) count_row("Completed, by order", funnel_flow$order[k], funnel_flow$completed[k],
                                                                     funnel_flow$pct_completed[k]))),
  bind_rows(lapply(seq_len(nrow(kept_flow)), function(k) count_row("Kept, by order", kept_flow$order[k], kept_flow$kept[k]))),
  bind_rows(lapply(seq_len(nrow(kept_flow)), function(k) count_row("Kept at 3.0 degrees, by order", kept_flow$order[k], kept_flow$kept_strict[k]))))

# ---- STEP 10. H1: Engagement, visual versus narrative ------------------------------------------
cat("\n---- STEP 10. H1: percent of time Engaged, foodwaste_visual versus foodwaste_narrative ----\n")
res_h1 <- report_paired(w$Engagement_narr, w$Engagement_vis,
                        sprintf("H1: Engagement (percent of time above 50), kept respondents, n = %d", nrow(w)),
                        "foodwaste_narrative", "foodwaste_visual", "H1", " percentage points")
cat(sprintf("Respondents with Engagement exactly 0: narrative %d (%.1f percent), visual %d (%.1f percent); both 0: %d\n",
            sum(w$Engagement_narr == 0), 100 * mean(w$Engagement_narr == 0), sum(w$Engagement_vis == 0), 100 * mean(w$Engagement_vis == 0),
            sum(w$Engagement_narr == 0 & w$Engagement_vis == 0)))
cat(sprintf("Median difference = %.2f percentage points; the Wilcoxon test compares ranks, so the many zeros and the long right tail do not drive it.\n",
            median(res_h1$d)))
if (has_effectsize) {
  es_chk <- effectsize::cohens_d(res_h1$d, ci = 0.95, verbose = FALSE)
  cat(sprintf("Cross-check with the effectsize package: d_z = %.4f, 95%% CI [%.4f, %.4f] (hand computed: %.4f [%.4f, %.4f])\n",
              es_chk$Cohens_d, es_chk$CI_low, es_chk$CI_high, res_h1$es, res_h1$es_lo, res_h1$es_hi))
}
cat("\n")

# ---- STEP 11. H2: dwell time on the four tips ---------------------------------------------------
# Friedman's test is the rank based test for one group measured under several conditions: within each
# respondent the four tips are ranked 1 to 4, and the test asks whether the mean ranks differ.
# Kendall's W = Friedman chi square / (n (k - 1)) runs from 0 (no agreement among respondents about the
# order of the tips) to 1 (every respondent ranks the tips the same way). The follow up compares every
# pair with a Wilcoxon signed rank test and controls the six comparisons with Holm's method.
cat("---- STEP 11. H2: dwell time on the four tip AOIs (infographic) ----\n")
aoi_k <- aoi %>% filter(id %in% w$id)
rm_tab <- aoi_k %>% group_by(aoi) %>%
  summarize(n = n(), size_px2 = first(size_px), size_pct = first(size_pct), hit_ratio_pct = 100 * mean(hit),
            dwell_mean = mean(dwell0), dwell_sd = sd(dwell0), dwell_median = median(dwell0), dwell_pct_mean = mean(coalesce(dwell_pct, 0)),
            ttff_median = median(ttff, na.rm = TRUE), fix_count_mean = mean(coalesce(fixn, 0)), .groups = "drop") %>%
  mutate(aoi = factor(aoi, levels = c("Headline", TIPS))) %>% arrange(aoi)
D <- as.matrix(w[, paste0("dwell_", TIPS)]); colnames(D) <- TIPS
mean_ranks <- colMeans(t(apply(D, 1, rank)))
rm_tab$mean_rank_tips <- c(NA, round(mean_ranks, 3))
cat("Repeated measures descriptive table (kept respondents; dwell time 0 when the AOI was never fixated; hit ratio = the\n")
cat("percent of respondents with at least one fixation in the AOI, which iMotions calls Respondent ratio (%)):\n")
print(as.data.frame(rm_tab %>% mutate(across(where(is.double), ~ round(.x, 1)))), row.names = FALSE)
cat(sprintf("Mean rank of each tip (1 = least dwell, 4 = most, within each respondent): %s\n",
            paste(sprintf("%s %.2f", TIPS, mean_ranks), collapse = ", ")))
cat(sprintf("Respondents whose longest dwell was on Tip_1: %d of %d (%.1f percent)\n",
            sum(apply(D, 1, which.max) == 1), nrow(D), 100 * mean(apply(D, 1, which.max) == 1)))
h2_test <- function(D, label, id_prefix) {
  fr <- friedman.test(D)
  n <- nrow(D); k <- ncol(D)
  W <- unname(fr$statistic) / (n * (k - 1))
  cat(sprintf("%s\n", label))
  cat(sprintf("  Friedman chi square(%d) = %.2f, p = %s, n = %d; Kendall's W = %.3f\n", as.integer(fr$parameter), fr$statistic,
              pf(fr$p.value), n, W))
  prs <- combn(colnames(D), 2)
  pw <- bind_rows(lapply(seq_len(ncol(prs)), function(j) {
    a <- prs[1, j]; b <- prs[2, j]; d <- D[, a] - D[, b]
    wx <- suppressWarnings(wilcox.test(D[, a], D[, b], paired = TRUE, exact = FALSE))
    tibble(pair = paste(a, "vs", b), a = a, b = b, mean_a = mean(D[, a]), mean_b = mean(D[, b]), mean_diff = mean(d), sd_diff = sd(d),
           median_diff = median(d), dz = mean(d) / sd(d), n_a_more = sum(d > 0), n_b_more = sum(d < 0), n_tie = sum(d == 0),
           V = unname(wx$statistic), p = wx$p.value)
  })) %>% mutate(p_holm = p.adjust(p, method = "holm"), sig_holm = p_holm < .05)
  cat("  Pairwise Wilcoxon signed rank tests, Holm adjusted (mean_diff and median_diff in ms, first AOI minus second):\n")
  print(as.data.frame(pw %>% transmute(pair, mean_diff = round(mean_diff, 1), median_diff = round(median_diff, 1), dz = round(dz, 3),
                                       n_a_more, n_b_more, V = fv(V), p = pf(p), p_holm = pf(p_holm), sig_holm)), row.names = FALSE)
  cat(sprintf("  Pairs significant after the Holm adjustment: %d of %d\n\n", sum(pw$sig_holm), nrow(pw)))
  r <- res_template(paste0(id_prefix, "_FRIEDMAN"), "Friedman test", label)
  r[c("n", "stat_name", "stat", "df", "p", "es_type", "es")] <- list(n, "Friedman chi square", unname(fr$statistic), unname(fr$parameter),
                                                                    fr$p.value, "Kendall's W", W)
  rows <- lapply(seq_len(nrow(pw)), function(j) {
    rr <- res_template(sprintf("%s_PAIR_%s_%s", id_prefix, pw$a[j], pw$b[j]), "Wilcoxon signed rank (paired), Holm adjusted",
                       sprintf("%s: %s, dwell time (ms)", label, pw$pair[j]))
    rr[c("n", "m1", "m2", "diff", "sd_diff", "stat_name", "stat", "p", "p_holm", "es_type", "es", "np_test", "np_stat", "np_p")] <-
      list(n, pw$mean_a[j], pw$mean_b[j], pw$mean_diff[j], pw$sd_diff[j], "Wilcoxon V", pw$V[j], pw$p[j], pw$p_holm[j], "d_z (descriptive)",
           pw$dz[j], "Wilcoxon signed rank V", pw$V[j], pw$p[j])
    rr$note <- sprintf("median difference %.1f ms; %d of %d respondents dwelled longer on %s", pw$median_diff[j], pw$n_a_more[j], n, pw$a[j])
    rr
  })
  list(fr = r, pairs = rows, pw = pw, W = W, fr_raw = fr, n = n)
}
h2 <- h2_test(D, sprintf("H2: dwell time (ms) on Tip_1 to Tip_4, kept respondents, n = %d", nrow(D)), "H2")
cat("Reading the result: Tip_1 (top left) drew the most dwell time and was ranked first by most respondents; the other\n")
cat("three tips are close to each other. Position on the page (Tip_1 is read first) and content are confounded here.\n\n")

# ---- STEP 12. H3: intention by order -----------------------------------------------------------
# The two orders differ only in which video came first, and the order was assigned at random. A test of
# a variable measured AFTER both videos therefore asks two things at once: did randomization give
# comparable groups, and did the order carry over to the questionnaire (an order effect)? A
# NONSIGNIFICANT result is what randomization predicts. A significant one would mean either a chance
# imbalance (expected in 5 percent of such tests) or a real order effect; the analysis would then report
# intention separately by order or include order as a factor, and the attrition check in step 5 would
# matter even more.
cat("---- STEP 12. H3: intention to reduce food waste by order (randomization check) ----\n")
res_h3 <- report_welch(w$intention[w$order == "Narrative first"], w$intention[w$order == "Visual first"],
                       sprintf("H3: Intention_reduce_food_waste_1to7, Narrative first versus Visual first, n = %d and %d",
                               sum(w$order == "Narrative first"), sum(w$order == "Visual first")),
                       "Narrative first", "Visual first", "H3")
cat("Distribution of the answers (1 to 7) by order:\n"); print(table(w$order, w$intention))
cat("\n")

# ---- STEP 13. Calibration accuracy and the hit on the smallest AOI -----------------------------------
# The Headline is the smallest AOI: a wide but thin banner. With a webcam, a respondent whose gaze
# estimate is off by 3 or 4 degrees can look straight at it and still be recorded above or below it.
# Hit = at least one fixation inside the AOI. The infographic came between the two calibrations, so the
# mean of the two accuracies is the best single estimate of the error while it was on screen. This
# analysis uses EVERY completed respondent whose eye tracking quality and face quality passed the rule,
# whatever the accuracy (so it includes the respondents excluded only for accuracy): missing samples
# would also remove hits, and leaving out the low quality respondents keeps that from blurring the
# picture. Logistic regression gives the odds ratio per degree.
cat("---- STEP 13. Calibration accuracy and the AOI hit on the smallest AOI (Headline) ----\n")
sizes <- aoi %>% distinct(aoi, size_px, size_pct) %>% arrange(size_px)
cat("AOI sizes (Size (px2), Size (%)):\n"); print(as.data.frame(sizes), row.names = FALSE)
cat(sprintf("Smallest AOI: %s\n", sizes$aoi[1]))
hq <- w_all %>% filter(!f_etq & !f_face)
fit_hit <- glm(hit_Headline ~ mean_acc, family = binomial, data = hq)
cf_hit <- summary(fit_hit)$coefficients
ci_hit <- suppressMessages(confint(fit_hit))
or_hit <- exp(cf_hit["mean_acc", "Estimate"]); or_lo <- exp(ci_hit["mean_acc", 1]); or_hi <- exp(ci_hit["mean_acc", 2])
cat(sprintf("Sample: completed respondents whose eye tracking and face quality passed: n = %d (%d of them excluded for accuracy only), %d hits (%.1f percent)\n",
            nrow(hq), sum(!hq$keep), sum(hq$hit_Headline), 100 * mean(hq$hit_Headline)))
cat(sprintf("Mean calibration accuracy in this sample: M = %.2f, SD = %.2f, range %.2f to %.2f degrees\n",
            mean(hq$mean_acc), sd(hq$mean_acc), min(hq$mean_acc), max(hq$mean_acc)))
cat(sprintf("Logistic regression: logit(P(hit)) = %.3f %+.3f x mean accuracy\n", cf_hit[1, 1], cf_hit[2, 1]))
cat(sprintf("  b = %.3f, SE = %.3f, Wald z = %.2f, p = %s; odds ratio per degree = %.2f, 95%% CI [%.2f, %.2f] (profile likelihood)\n",
            cf_hit[2, 1], cf_hit[2, 2], cf_hit[2, 3], pf(cf_hit[2, 4]), or_hit, or_lo, or_hi))
pr <- predict(fit_hit, newdata = data.frame(mean_acc = c(1, 2, 3, 4)), type = "response")
cat(sprintf("  Predicted hit probability at 1, 2, 3, 4 degrees: %s\n", paste(sprintf("%.2f", pr), collapse = ", ")))
fit_k <- glm(hit_Headline ~ mean_acc, family = binomial, data = w)
cat(sprintf("  Kept respondents only (accuracy 4.0 or less by the rule, n = %d): b = %.3f, SE = %.3f, p = %s; odds ratio = %.2f\n",
            nrow(w), coef(fit_k)[2], summary(fit_k)$coefficients[2, 2], pf(summary(fit_k)$coefficients[2, 4]), exp(coef(fit_k)[2])))
band_lab <- c("1.5 or less", "1.5 to 2.5", "2.5 to 3.5", "above 3.5")
bands <- hq %>% mutate(band = cut(mean_acc, c(0, 1.5, 2.5, 3.5, Inf), labels = band_lab)) %>% group_by(band) %>%
  summarize(n = n(), excluded_accuracy = sum(!keep), hits = sum(hit_Headline), hit_ratio_pct = round(100 * mean(hit_Headline), 1),
            all_tips_hit_pct = round(100 * mean(hit_Tip_1 & hit_Tip_2 & hit_Tip_3 & hit_Tip_4), 1), .groups = "drop")
cat("Headline hit ratio by mean calibration accuracy (degrees); excluded_accuracy = respondents in the band excluded because a\n")
cat("calibration was above 4.0; all_tips_hit_pct = percent who hit all four large tips:\n")
print(as.data.frame(bands), row.names = FALSE)
cat("The large tips are hit by nearly everyone at any accuracy; the thin Headline loses hits as accuracy worsens. A wide banner\n")
cat("still catches gaze when the error is sideways, which is why the hit ratio levels off instead of falling to zero.\n\n")
res_hit <- res_template("HIT_HEADLINE", "logistic regression (hit on accuracy)",
                        "Headline hit (at least one fixation) on mean calibration accuracy, completed respondents with eye tracking and face quality passed")
res_hit[c("n", "m1", "stat_name", "stat", "p", "es_type", "es", "es_lo", "es_hi")] <-
  list(nrow(hq), mean(hq$hit_Headline), "Wald z", cf_hit[2, 3], cf_hit[2, 4], "odds ratio per degree", or_hit, or_lo, or_hi)
res_hit$note <- sprintf("b = %.3f, SE = %.3f; predicted hit at 1, 2, 3, 4 degrees: %s", cf_hit[2, 1], cf_hit[2, 2], paste(sprintf("%.2f", pr), collapse = ", "))
head_sz <- sizes %>% filter(aoi == "Headline"); tip_sz <- sizes %>% filter(aoi == "Tip_1")

# ---- STEP 14. Sensitivity: the 3.0 degree threshold ---------------------------------------------
cat("---- STEP 14. Sensitivity: accuracy 3.0 degrees or less at both calibrations ----\n")
ws <- w %>% filter(keep_strict)
cat(sprintf("Kept: %d of %d (a further %d removed; Narrative first %d, Visual first %d)\n", nrow(ws), nrow(w), nrow(w) - nrow(ws),
            sum(ws$order == "Narrative first"), sum(ws$order == "Visual first")))
res_s1 <- report_paired(ws$Engagement_narr, ws$Engagement_vis, sprintf("Sensitivity H1 (3.0 degrees), n = %d", nrow(ws)),
                        "foodwaste_narrative", "foodwaste_visual", "S30_H1", " percentage points")
Ds <- as.matrix(ws[, paste0("dwell_", TIPS)]); colnames(Ds) <- TIPS
h2s <- h2_test(Ds, sprintf("Sensitivity H2 (3.0 degrees): dwell time on the four tips, n = %d", nrow(Ds)), "S30_H2")
res_s3 <- report_welch(ws$intention[ws$order == "Narrative first"], ws$intention[ws$order == "Visual first"],
                       sprintf("Sensitivity H3 (3.0 degrees), n = %d and %d", sum(ws$order == "Narrative first"), sum(ws$order == "Visual first")),
                       "Narrative first", "Visual first", "S30_H3")
cat(sprintf("Summary: H1 d_z %.2f -> %.2f; H2 Kendall's W %.3f -> %.3f with %d -> %d significant pairs; H3 p %s -> %s.\n\n",
            res_h1$es, res_s1$es, h2$W, h2s$W, sum(h2$pw$sig_holm), sum(h2s$pw$sig_holm), pf(res_h3$p), pf(res_s3$p)))

# ---- STEP 15. Exploratory ---------------------------------------------------------------------
cat("---- STEP 15. Exploratory analyses ----\n")
cor_report <- function(x, y, label, id, method_note = "") {
  ct <- cor.test(x, y)
  sp <- suppressWarnings(cor.test(x, y, method = "spearman", exact = FALSE))
  cat(sprintf("%s: r(%d) = %.2f, 95%% CI [%.2f, %.2f], p = %s; Spearman rho = %.2f, p = %s %s\n",
              label, as.integer(ct$parameter), ct$estimate, ct$conf.int[1], ct$conf.int[2], pf(ct$p.value),
              sp$estimate, pf(sp$p.value), method_note))
  r <- res_template(id, "correlation", label)
  r[c("n", "stat_name", "stat", "df", "p", "es_type", "es", "es_lo", "es_hi", "np_test", "np_stat", "np_p")] <-
    list(length(x), "t", unname(ct$statistic), unname(ct$parameter), ct$p.value, "Pearson r", unname(ct$estimate),
         ct$conf.int[1], ct$conf.int[2], "Spearman rho", unname(sp$estimate), sp$p.value)
  r
}
res_e1 <- cor_report(w$eng_diff, w$pref_visual, "(a) Engagement difference (visual minus narrative) with preference (1 = Visual)", "EXP_PREF",
                     "(point biserial)")
pg <- w %>% group_by(pref) %>% summarize(n = n(), m = mean(eng_diff), s = sd(eng_diff), .groups = "drop")
cat(sprintf("    Engagement difference by stated preference: Visual M = %.2f (SD = %.2f, n = %d), Narrative M = %.2f (SD = %.2f, n = %d)\n",
            pg$m[pg$pref == "Visual"], pg$s[pg$pref == "Visual"], pg$n[pg$pref == "Visual"],
            pg$m[pg$pref == "Narrative"], pg$s[pg$pref == "Narrative"], pg$n[pg$pref == "Narrative"]))
res_e2 <- cor_report(w$tips_dwell, w$recall, "(b) Total dwell time on the four tips (ms) with tips recalled (0 to 4)", "EXP_RECALL")
rec_tab <- w %>% group_by(recall) %>% summarize(n = n(), tips_dwell_mean = round(mean(tips_dwell)), .groups = "drop")
cat("    Mean total tip dwell (ms) by number of tips recalled:\n"); print(as.data.frame(rec_tab), row.names = FALSE)
cat("Both are correlations in a self selected sample with no hypothesis: they describe, they do not show causes.\n\n")

