       subtitle = sprintf("AFFDEX Engagement above 50; each line is one respondent (dashed = lower for the visual video). n = %d.\nDifference M = %.1f percentage points, 95%% CI [%.1f, %.1f]; t(%d) = %.2f, %s;\nd_z = %.2f, 95%% CI [%.2f, %.2f]; Wilcoxon signed rank %s.",
                          res_h1$n, res_h1$diff, res_h1$ci_lo, res_h1$ci_hi, as.integer(res_h1$df), res_h1$stat, fp(res_h1$p),
                          res_h1$es, res_h1$es_lo, res_h1$es_hi, fp(res_h1$np_p)),
       x = NULL, y = "Percent of time present (Engagement)",
       caption = wrap_txt(sprintf("SIMULATED teaching data (make_simulated_data.py), not real viewers. Faces recorded by the respondents' own webcams, scored in iMotions Lab after download. %d respondents (%.0f percent) were never above the threshold during the narrative video, which is why the mean sits above the median and the Wilcoxon test is the check.",
                                  sum(w$Engagement_narr == 0), 100 * mean(w$Engagement_narr == 0)), 130)) +
  theme_rdc()
save_fig(fig2, "SIMULATED_fig2_engagement_by_video.png", 1000)

# Figure 3: dwell time on the four tips, respondents, means with 95% CIs, Holm significant pairs.
f3 <- w %>% select(id, all_of(paste0("dwell_", TIPS))) %>% pivot_longer(-id, names_to = "aoi", values_to = "y") %>%
  mutate(aoi = sub("dwell_", "", aoi), x = match(aoi, TIPS))
f3_mean <- f3 %>% group_by(aoi, x) %>% summarize(mean = mean(y), ci = ci95(y), .groups = "drop") %>%
  left_join(rm_tab %>% transmute(aoi = as.character(aoi), hit_ratio_pct, ttff_median), by = "aoi") %>%
  mutate(mrank = mean_ranks[aoi])
sig <- h2$pw %>% filter(sig_holm) %>% mutate(x1 = match(a, TIPS), x2 = match(b, TIPS)) %>% arrange(x2 - x1, x1)
ymax <- max(f3$y)
sig <- sig %>% mutate(ypos = ymax * 1.04 + (row_number() - 1) * ymax * 0.075)
set.seed(6)
fig3 <- ggplot() +
  geom_jitter(data = f3, aes(x = x, y = y), width = 0.17, height = 0, color = col_sky, alpha = 0.55, size = 1.5) +
  geom_errorbar(data = f3_mean, aes(x = x + 0.3, ymin = mean - ci, ymax = mean + ci), width = 0.07, linewidth = 1, color = col_dark) +
  geom_point(data = f3_mean, aes(x = x + 0.3, y = mean), size = 3.8, shape = 18, color = col_dark) +
  geom_text(data = f3_mean, aes(x = x + 0.36, y = mean, label = sprintf("M = %.0f", mean)), hjust = 0, size = 3.4) +
  geom_segment(data = sig, aes(x = x1, xend = x2, y = ypos, yend = ypos), linewidth = 0.5) +
  geom_text(data = sig, aes(x = (x1 + x2) / 2, y = ypos, label = sprintf("Holm p %s", sub("^p ", "", fp(p_holm)))), vjust = -0.35, size = 3.1) +
  scale_x_continuous(breaks = 1:4, labels = sprintf("%s\nmean rank %.2f\nhit ratio %.0f%%\nTTFF median %.0f ms", f3_mean$aoi, f3_mean$mrank,
                                                    f3_mean$hit_ratio_pct, f3_mean$ttff_median), limits = c(0.6, 4.75)) +
  labs(title = "SIMULATED: dwell time on the four tips of the infographic (15 s)",
       subtitle = sprintf("Each dot is one respondent (0 = never fixated); mean with 95%% CI in black. n = %d.\nFriedman X2(3) = %.1f, %s; Kendall's W = %.2f. Brackets: pairs that differ after the Holm adjustment.",
                          h2$n, h2$fr$stat, fp(h2$fr$p), h2$W),
       x = NULL, y = "Dwell time (ms)",
       caption = wrap_txt(sprintf("SIMULATED teaching data (make_simulated_data.py), not real viewers. Webcam eye tracking; the four tip AOIs are equal in size (%d px2, %.1f percent of the screen each) and separated by gaps, as advised for webcam data. Tip_1 sits top left and is read first, so its position and its content cannot be separated here.", tip_sz$size_px, tip_sz$size_pct), 130)) +
  theme_rdc()
save_fig(fig3, "SIMULATED_fig3_tip_dwell.png", 1050)

# Figure 4: calibration drift (left) and the Headline hit by accuracy (right), two panels on one page.
f4 <- w_all %>% mutate(status = case_when(
  f_pre | f_post ~ "Excluded: a calibration above 4.0",
  !keep ~ "Excluded: eye tracking or face quality",
  !keep_strict ~ "Kept, removed at 3.0 (sensitivity)",
  TRUE ~ "Kept at both thresholds"))
st_cols <- c(`Kept at both thresholds` = col_gray, `Kept, removed at 3.0 (sensitivity)` = col_orange,
             `Excluded: a calibration above 4.0` = col_purple, `Excluded: eye tracking or face quality` = col_green)
st_shapes <- c(`Kept at both thresholds` = 16, `Kept, removed at 3.0 (sensitivity)` = 17,
               `Excluded: a calibration above 4.0` = 15, `Excluded: eye tracking or face quality` = 4)
lim4 <- c(0, ceiling(max(c(f4$pre, f4$post))))
p4a <- ggplot(f4, aes(x = pre, y = post)) +
  annotate("rect", xmin = -Inf, xmax = ACC_MAX, ymin = ACC_MAX, ymax = Inf, fill = col_purple, alpha = 0.08) +
  geom_abline(slope = 1, intercept = 0, linetype = "dashed", color = "#555555") +
  geom_hline(yintercept = ACC_MAX, color = col_purple, linewidth = 0.6) + geom_vline(xintercept = ACC_MAX, color = col_purple, linewidth = 0.6) +
  geom_hline(yintercept = ACC_STRICT, color = col_orange, linewidth = 0.5, linetype = "dotted") +
  geom_vline(xintercept = ACC_STRICT, color = col_orange, linewidth = 0.5, linetype = "dotted") +
  geom_point(aes(color = status, shape = status), size = 2.1, alpha = 0.85) +
  annotate("label", x = 0.15, y = lim4[2] - 0.15, hjust = 0, vjust = 1, size = 3.2, color = col_purple, fill = "white", label.size = 0,
           label = sprintf("Shaded: Post-study above %.1f,\n%d respondents (%d of them\nwere fine at the start)", ACC_MAX, sum(qw$f_post), nrow(post_only))) +
  annotate("text", x = lim4[2] - 0.1, y = 0.35, hjust = 1, size = 3.1, color = "#555555", label = "dashed line: no change") +
  scale_color_manual(values = st_cols) + scale_shape_manual(values = st_shapes) +
  coord_equal(xlim = lim4, ylim = lim4) +
  guides(color = guide_legend(nrow = 2), shape = guide_legend(nrow = 2)) +
  labs(title = "A. Accuracy at the two calibrations",
       subtitle = sprintf("Completed respondents, n = %d.\nPost minus Pre: M = %.2f degrees, 95%% CI [%.2f, %.2f];\nt(%d) = %.2f, %s; d_z = %.2f.",
                          res_drift$n, res_drift$diff, res_drift$ci_lo, res_drift$ci_hi, as.integer(res_drift$df), res_drift$stat,
                          fp(res_drift$p), res_drift$es),
       x = "Pre-study calibration accuracy (degrees)", y = "Post-study calibration accuracy (degrees)") +
  theme_rdc(11) + theme(legend.text = element_text(size = 8.5), plot.subtitle = element_text(size = 9.5, color = "#555555"),
                        panel.grid.major.x = element_line(color = "#E3E3E3", linewidth = 0.4))
b4 <- bands %>% mutate(band = factor(band, levels = band_lab),
                       lo = 100 * qbeta(0.025, hits + 0.5, n - hits + 0.5), hi = 100 * qbeta(0.975, hits + 0.5, n - hits + 0.5))
p4b <- ggplot(b4, aes(x = band, y = hit_ratio_pct)) +
  geom_col(width = 0.65, fill = col_narr) +
  geom_errorbar(aes(ymin = lo, ymax = hi), width = 0.15, color = col_dark) +
  geom_text(aes(y = 4, label = sprintf("%.0f%%\nn = %d", hit_ratio_pct, n)), vjust = 0, color = "white", size = 3.3, fontface = "bold") +
  geom_text(aes(y = hi + 2, label = ifelse(excluded_accuracy > 0, sprintf("%d excluded\nfor accuracy", excluded_accuracy), "")),
            vjust = 0, size = 2.9, color = col_purple) +
  scale_y_continuous(limits = c(0, 112), breaks = seq(0, 100, 20)) +
  scale_x_discrete(labels = function(x) gsub(" to ", "\nto ", x)) +
  labs(title = "B. Hit on the smallest AOI (Headline)",
       subtitle = sprintf("Percent with a fixation inside the Headline,\nby mean accuracy (eye tracking and face\nquality passed, n = %d); 95%% interval (Jeffreys).\nOdds ratio per degree = %.2f,\n95%% CI [%.2f, %.2f], %s.",
                          nrow(hq), or_hit, or_lo, or_hi, fp(cf_hit[2, 4])),
       x = "Mean of the two accuracies (degrees)", y = "Headline hit ratio (%)") +
  theme_rdc(11) + theme(plot.subtitle = element_text(size = 9.5, color = "#555555"))
png(file.path(fig_dir, "SIMULATED_fig4_calibration_drift.png"), width = 1400, height = 1000, res = 150)
grid.newpage()
pushViewport(viewport(layout = grid.layout(3, 2, heights = unit(c(0.07, 0.86, 0.07), "npc"), widths = unit(c(0.58, 0.42), "npc"))))
grid.text("SIMULATED: webcam calibration drift and what it does to a small AOI", x = 0.02, hjust = 0, gp = gpar(fontface = "bold", fontsize = 15),
          vp = viewport(layout.pos.row = 1, layout.pos.col = 1:2))
print(p4a, vp = viewport(layout.pos.row = 2, layout.pos.col = 1))
print(p4b, vp = viewport(layout.pos.row = 2, layout.pos.col = 2))
grid.text(wrap_txt(sprintf("SIMULATED teaching data (make_simulated_data.py), not real respondents. Lines: the %.1f degree rule (solid) and the %.1f degree sensitivity threshold (dotted). The Headline covers %.1f percent of the screen (%d px2) as a wide, thin banner about 2.4 degrees tall; each tip covers %.1f percent (%d px2).", ACC_MAX, ACC_STRICT, head_sz$size_pct, head_sz$size_px, tip_sz$size_pct, tip_sz$size_px), 150),
          x = 0.02, hjust = 0, gp = gpar(fontsize = 8.5, col = "#777777"), vp = viewport(layout.pos.row = 3, layout.pos.col = 1:2))
invisible(dev.off())
cat("saved figure: figures/SIMULATED_fig4_calibration_drift.png\n\n")

