row_of <- function(r) tibble(id = r$id, test = r$test, comparison = r$label, n = r$n, n1 = r$n1, n2 = r$n2,
                             m1 = r$m1, m2 = r$m2, sd1 = r$sd1, sd2 = r$sd2, mean_diff = r$diff, sd_diff = r$sd_diff,
                             sd_pooled = r$sd_pooled, diff_ci_low = r$ci_lo, diff_ci_high = r$ci_hi, statistic_name = r$stat_name,
                             statistic = r$stat, df = r$df, p = r$p, p_holm = r$p_holm, es_type = r$es_type, es = r$es,
                             es_ci_low = r$es_lo, es_ci_high = r$es_hi, es_ci_low_approx = r$es_lo_approx, es_ci_high_approx = r$es_hi_approx,
                             g = r$g, g_ci_low = r$g_lo, g_ci_high = r$g_hi, g_ci_low_approx = r$g_lo_approx, g_ci_high_approx = r$g_hi_approx,
                             nonparam_test = r$np_test, nonparam_stat = r$np_stat, nonparam_p = r$np_p, shapiro_p = r$shapiro_p, note = r$note)
